macro_rules! polyfills {
    () => {
        # [doc = " Since we support multiple versions of Rust, there are often features which"] # [doc = " have been stabilized in the most recent stable release which do not yet"] # [doc = " exist (stably) on our MSRV. This module provides polyfills for those"] # [doc = " features so that we can write more \"modern\" code, and just remove the"] # [doc = " polyfill once our MSRV supports the corresponding feature. Without this,"] # [doc = " we'd have to write worse/more verbose code and leave FIXME comments sprinkled"] # [doc = " throughout the codebase to update to the new pattern once it's stabilized."] # [doc = ""] # [doc = " Each trait is imported as `_` at the crate root; each polyfill should \"just"] # [doc = " work\" at usage sites."] pub (crate) mod polyfills { use core :: ptr :: { self , NonNull } ; # [allow (unused)] pub (crate) trait NonNullExt < T > { fn slice_from_raw_parts (data : Self , len : usize) -> NonNull < [T] > ; } impl < T > NonNullExt < T > for NonNull < T > { # [cfg_attr (all (coverage_nightly , __ZEROCOPY_INTERNAL_USE_ONLY_NIGHTLY_FEATURES_IN_TESTS) , coverage (off))] # [inline (always)] fn slice_from_raw_parts (data : Self , len : usize) -> NonNull < [T] > { let ptr = ptr :: slice_from_raw_parts_mut (data . as_ptr () , len) ; unsafe { NonNull :: new_unchecked (ptr) } } } # [allow (unused)] pub (crate) trait NumExt { # [doc = " Add without checking for overflow."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The caller promises that the addition will not overflow."] unsafe fn unchecked_add (self , rhs : Self) -> Self ; # [doc = " Subtract without checking for underflow."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The caller promises that the subtraction will not underflow."] unsafe fn unchecked_sub (self , rhs : Self) -> Self ; # [doc = " Multiply without checking for overflow."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The caller promises that the multiplication will not overflow."] unsafe fn unchecked_mul (self , rhs : Self) -> Self ; } impl NumExt for usize { # [cfg_attr (all (coverage_nightly , __ZEROCOPY_INTERNAL_USE_ONLY_NIGHTLY_FEATURES_IN_TESTS) , coverage (off))] # [inline (always)] unsafe fn unchecked_add (self , rhs : usize) -> usize { match self . checked_add (rhs) { Some (x) => x , None => { unsafe { core :: hint :: unreachable_unchecked () } } } } # [cfg_attr (all (coverage_nightly , __ZEROCOPY_INTERNAL_USE_ONLY_NIGHTLY_FEATURES_IN_TESTS) , coverage (off))] # [inline (always)] unsafe fn unchecked_sub (self , rhs : usize) -> usize { match self . checked_sub (rhs) { Some (x) => x , None => { unsafe { core :: hint :: unreachable_unchecked () } } } } # [cfg_attr (all (coverage_nightly , __ZEROCOPY_INTERNAL_USE_ONLY_NIGHTLY_FEATURES_IN_TESTS) , coverage (off))] # [inline (always)] unsafe fn unchecked_mul (self , rhs : usize) -> usize { match self . checked_mul (rhs) { Some (x) => x , None => { unsafe { core :: hint :: unreachable_unchecked () } } } } } }
    };
}

polyfills!()